INSERT INTO `danh_muc` VALUES (8,'Các tour khám phá bãi biển và hòn đảo nổi tiếng với cảnh đẹp, nước biển trong xanh và hoạt động nghỉ dưỡng.','Du lịch biển đảo'),(9,'Các tour tham quan rừng quốc gia, khu bảo tồn thiên nhiên và trải nghiệm môi trường sinh thái tự nhiên.','Du lịch sinh thái'),(10,'Các tour tham quan di tích lịch sử, làng nghề truyền thống và tìm hiểu văn hóa địa phương.','Du lịch văn hóa'),(11,'Các tour nghỉ dưỡng tại resort, khu du lịch cao cấp với dịch vụ thư giãn và chăm sóc sức khỏe.','Du lịch nghỉ dưỡng'),(12,'Các tour trải nghiệm thiên nhiên, trekking, leo núi và khám phá những địa điểm hoang sơ.','Du lịch khám phá');
