INSERT INTO `tour` VALUES (3500000.00,2,_binary '',8,4,3,'2026-03-05 04:26:20.593984','Khám phá vịnh kỳ quan Hạ Long 2n1đ','Trải nghiệm du thuyền trên vịnh với hàng nghìn đảo đá vôi tuyệt đẹp. Tham quan hang động, chèo kayak và thưởng thức hải sản tươi ngon.'),(4200000.00,3,_binary '',8,5,4,'2026-03-05 04:40:03.263307','Nghỉ dưỡng thiên đường biển Phú Quốc 3n1đ','Tận hưởng bãi biển cát trắng và làn nước trong xanh tại đảo ngọc Phú Quốc. Tham quan làng chài, chợ đêm và thưởng thức đặc sản địa phương.'),(2000000.00,2,_binary '',9,6,5,'2026-03-05 04:41:50.928163','Khám phá thiên nhiên Cúc Phương 2n1đ','Trekking trong rừng nguyên sinh và tìm hiểu hệ sinh thái đa dạng. Tham quan trung tâm cứu hộ động vật và trải nghiệm thiên nhiên hoang dã.'),(1200000.00,1,_binary '',9,7,6,'2026-03-05 04:42:59.253199','Trải nghiệm sinh thái Tràm Chim 1n0đ','Khám phá hệ sinh thái rừng ngập nước đặc trưng miền Tây. Ngồi xuồng len lỏi qua rừng tràm và ngắm các loài chim quý hiếm.'),(2500000.00,2,_binary '',10,8,7,'2026-03-05 04:44:30.481933','Hành trình di sản Hội An 2nn1đ','Dạo phố cổ lung linh ánh đèn lồng và tham quan các công trình kiến trúc cổ. Trải nghiệm ẩm thực đặc sản và văn hóa địa phương.'),(2700000.00,2,_binary '',10,9,8,'2026-03-05 04:45:29.338763','Khám phá di sản cố đô Huế 2n1đ','Tham quan Đại Nội, lăng tẩm vua Nguyễn và chùa Thiên Mụ. Thưởng thức ẩm thực cung đình và nét văn hóa đặc trưng xứ Huế.'),(3000000.00,3,_binary '',11,10,9,'2026-03-05 04:47:16.355137','Nghỉ dưỡng thành phố ngàn hoa 3n2đ','Khám phá thành phố sương mù với khí hậu mát mẻ quanh năm. Tham quan hồ Xuân Hương, thung lũng tình yêu và vườn hoa rực rỡ.'),(3800000.00,3,_binary '',11,11,10,'2026-03-05 04:48:14.981925','Nghỉ dưỡng biển Nha Trang 3n2đ','Thư giãn tại bãi biển đẹp và các khu resort cao cấp. Trải nghiệm lặn biển, tham quan đảo và thưởng thức hải sản tươi sống.'),(3200000.00,2,_binary '',12,13,11,'2026-03-05 04:49:07.485821','Chinh phục đỉnh Fansipan 2n1đ','Hành trình chinh phục nóc nhà Đông Dương đầy thử thách. Ngắm nhìn cảnh núi rừng Tây Bắc hùng vĩ từ độ cao hơn 3.000m.'),(25000000.00,4,_binary '',12,12,12,'2026-03-05 04:50:03.777480','Thám hiểm hang Sơn Đoòng 4n3đ','Khám phá hang động lớn nhất thế giới với cảnh quan kỳ vĩ. Trải nghiệm trekking, cắm trại trong hang và khám phá hệ sinh thái độc đáo.'),(1000000.00,1,_binary '',10,14,14,'2026-03-06 08:42:22.134212','Bạc Liêu- hành trình khám phá vùng đất công tử 1n0đ','Khám Phá Nhà Công Tử Bạc Liêu: Kiệt Tác Kiến Trúc Bề Thế Vượt Thời Gian Ở Miền Tây'),(890000.00,1,_binary '',9,28,15,'2026-03-12 06:52:10.530776','Khám phá Đồng Tháp – Làng hoa Sa Đéc 1N1Đ','Tham quan làng hoa Sa Đéc nổi tiếng và trải nghiệm văn hóa miền Tây.'),(3490000.00,3,_binary '',12,24,16,'2026-03-12 06:58:38.739731','Du lịch văn hóa Tây Nguyên 3N2Đ','Khám phá văn hóa cồng chiêng Tây Nguyên và tham quan buôn làng truyền thống.'),(6990000.00,3,_binary '',12,12,17,'2026-03-12 07:01:04.870372','Khám phá Hang Én 3N2Đ','Hành trình trekking và khám phá hang Én – hang động lớn thứ 3 thế giới.'),(1090000.00,1,_binary '',10,22,18,'2026-03-12 12:44:08.176059','Chinh phục núi Bà Đen 1N1Đ','Trải nghiệm trekking hoặc đi cáp treo lên đỉnh núi Bà Đen – nóc nhà Nam Bộ.'),(2390000.00,2,_binary '',12,21,19,'2026-03-12 12:46:21.467803','Khám phá Tây Bắc – Mộc Châu 2N1Đ','Khám phá cao nguyên Mộc Châu với đồi chè xanh và thác nước hùng vĩ.'),(1190000.00,1,_binary '',9,8,20,'2026-03-12 12:48:41.354445','Du lịch sinh thái Cù Lao Chàm 1N1Đ','Tham quan khu dự trữ sinh quyển thế giới Cù Lao Chàm và trải nghiệm lặn ngắm san hô.'),(2190000.00,2,_binary '',9,19,21,'2026-03-12 12:50:37.755491','Khám phá Vườn quốc gia Ba Bể 2N1Đ','Trải nghiệm hồ Ba Bể – một trong những hồ nước ngọt lớn nhất Việt Nam với phong cảnh thiên nhiên hoang sơ.'),(990.00,1,_binary '',9,18,22,'2026-03-12 12:52:23.133873','Trải nghiệm rừng tràm Trà Sư 1N1Đ','Khám phá rừng tràm Trà Sư bằng xuồng máy và tìm hiểu hệ sinh thái đặc trưng miền Tây.'),(2.49,2,_binary '',8,17,23,'2026-03-12 12:54:03.691162','Du lịch đảo Lý Sơn 2N1Đ','Khám phá đảo Lý Sơn – vương quốc tỏi với phong cảnh núi lửa và biển xanh tuyệt đẹp.'),(3290000.00,2,_binary '',8,16,24,'2026-03-12 12:56:15.405315','Khám phá Côn Đảo linh thiêng 2N1Đ','Hành trình khám phá Côn Đảo với bãi biển hoang sơ và các di tích lịch sử nổi tiếng.'),(2190000.00,2,_binary '',8,11,25,'2026-03-12 12:57:50.109006','Khám phá đảo Bình Ba 2N1Đ','Khám phá đảo Bình Ba với bãi biển hoang sơ và hải sản tươi sống nổi tiếng. Du khách có thể lặn ngắm san hô và thưởng thức đặc sản tôm hùm.');
